<script setup lang="ts">import{ref}from'vue';import{ElMessage}from'element-plus';import CrudForm from './crud/CrudForm.vue';defineProps<{modelValue:boolean}>();const emit=defineEmits<{(e:'update:modelValue',v:boolean):void;(e:'save',v:any):void}>();const model=ref({roleCode:'',roleName:''});const fields=[{code:'roleCode',label:'角色编码',type:'text',required:true,editable:true},{code:'roleName',label:'角色名称',type:'text',required:true,editable:true}];function submit(){if(!/^[a-z][a-z0-9:_-]{1,31}$/.test(model.value.roleCode)||!model.value.roleName.trim()){ElMessage.warning('请检查角色编码和名称');return}emit('save',{...model.value})}</script><template><CrudForm :model-value="modelValue" title="新增角色" :fields="fields" :model="model" @update:model-value="emit('update:modelValue',$event)" @update:model="model=$event" @submit="submit"/></template>
